/** トピックパスの高速検索用Set */
export const TOPIC_MASTER_SET: ReadonlySet<string> = new Set(TOPIC_MASTER);

/**
 * 指定パスがマスターリストに存在するか検証する
 * ※ トピック名に "/" を含む場合があるため、完全一致で検索する
 */
export function isValidTopic(path: string): boolean {
  return TOPIC_MASTER_SET.has(path);
}

/** 指定科目のトピック一覧を取得する */
export function getTopicsForSubject(subject: string): string[] {
  const prefix = subject + "/";
  return TOPIC_MASTER.filter((t) => t.startsWith(prefix));
}
